insert into public.services (id, slug, ordre, publie, nom, theme, picto, photo, photo_alt, rotation, accroche, sous_titre, chapo, ariane, description_seo, horaires, telephone, contact) values ('toudi-boudji', 'toudi-boudji', 4, true, 'Toudi Boudji', 'vert', 'm-picto-toudi-boudji', 'm-service-toudi-boudji', 'Trois hommes de dos, bras sur les épaules', -1.5, 'On avance mieux à plusieurs.', 'Insertion sociale et entraide', '', 'Nos services', '', '[{"jours":"Du lundi au vendredi","heures":"9h-16h30"}]'::jsonb, '', '') on conflict (id) do update set slug = excluded.slug, ordre = excluded.ordre, publie = excluded.publie, nom = excluded.nom, theme = excluded.theme, picto = excluded.picto, photo = excluded.photo, photo_alt = excluded.photo_alt, rotation = excluded.rotation, accroche = excluded.accroche, sous_titre = excluded.sous_titre, chapo = excluded.chapo, ariane = excluded.ariane, description_seo = excluded.description_seo, horaires = excluded.horaires, telephone = excluded.telephone, contact = excluded.contact;
insert into public.services (id, slug, ordre, publie, nom, theme, picto, photo, photo_alt, rotation, accroche, sous_titre, chapo, ariane, description_seo, transversal, bloc_transversal_sur, bloc_transversal_texte, bloc_transversal_bouton, horaires, telephone, contact) values ('promotion-sante', 'promotion-sante', 5, true, 'Promotion de la santé', 'mauve', '', '', '', 0, 'La santé pour avancer plus loin', 'Un accompagnement transversal', 'La santé fait partie du chemin. Nous créons des occasions simples de parler, de prévenir, de recevoir des soins et de retrouver confiance, sans jugement et au rythme de chacun.', 'Nos services', '', true, 'Transversal', 'Prendre soin de soi aide aussi à reprendre pied. Depuis 2023, notre programme de promotion de la santé réunit prévention, partage d’expérience et accompagnement. Un médecin bénévole, une infirmière, une psychologue et une équipe de soins à domicile travaillent ensemble, au plus près des personnes.', 'Lire plus', '[]'::jsonb, '', '') on conflict (id) do update set slug = excluded.slug, ordre = excluded.ordre, publie = excluded.publie, nom = excluded.nom, theme = excluded.theme, picto = excluded.picto, photo = excluded.photo, photo_alt = excluded.photo_alt, rotation = excluded.rotation, accroche = excluded.accroche, sous_titre = excluded.sous_titre, chapo = excluded.chapo, ariane = excluded.ariane, description_seo = excluded.description_seo, transversal = excluded.transversal, bloc_transversal_sur = excluded.bloc_transversal_sur, bloc_transversal_texte = excluded.bloc_transversal_texte, bloc_transversal_bouton = excluded.bloc_transversal_bouton, horaires = excluded.horaires, telephone = excluded.telephone, contact = excluded.contact;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('rb-1', '/services/le-rebond', 'duo', 1, true, '{"sur":"Ici, on peut souffler","colonnes":[{"etiquette":"En quelques mots","pinceau":"rouge","titre":"L’accueil d’urgence et l’accompagnement en journée","paragraphes":["Au Rebond, chacun peut d’abord souffler, manger, se laver et être écouté. C’est souvent dans ces moments simples qu’un lien se crée. À partir de là, nos équipes peuvent accompagner les premières démarches et ouvrir, avec la personne, un chemin vers la suite."]},{"etiquette":"Pour qui ?","pinceau":"jaune","paragraphes":["Les personnes sans-abri ou en situation de grande précarité qui ont besoin d’un accueil de jour, de répondre à leurs besoins primaires ou d’être accompagnées."]}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('rb-2', '/services/le-rebond', 'etapes', 2, true, '{"titre":"Une journée au Rebond","paragraphes":["Dans notre centre d’accueil, ouvert 7j/7 et 365 jours par an, les personnes peuvent se poser, se restaurer et dialoguer dans un cadre convivial. Elles peuvent prendre une douche, utiliser les toilettes, bénéficier de la machine à laver, et faire appel à une infirmière et une psychologue."],"image":"m-rebond-repas","image_alt":"Un repas partagé au Rebond","rotation":-1.5,"etapes":[{"titre":"Se poser, se restaurer et dialoguer"},{"titre":"Prendre une douche et utiliser les toilettes"},{"titre":"Utiliser la machine à laver"},{"titre":"Faire appel à une infirmière"},{"titre":"Rencontrer une psychologue"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('rb-3', '/services/le-rebond', 'chiffres', 3, true, '{"titre":"Le Rebond en chiffres (2023)","contexte":"service","service":"le-rebond"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('rb-4', '/services/le-rebond', 'graphique', 4, true, '{"service":"le-rebond","graphique":"Démarches par catégorie","titre":"Les démarches par catégorie (2023)","paragraphes":["Avant de penser au long terme, il faut pouvoir manger, se laver, se reposer et prendre soin de sa santé. Ces besoins essentiels sont le point de départ de tout accompagnement."],"note":"17 567 démarches répertoriées en 2023."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('rb-5', '/services/le-rebond', 'infos', 5, true, '{"service":"le-rebond"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
