insert into public.sections (id, page, type, ordre, publie, contenu) values ('ct-1', '/services/chez-toit', 'duo', 1, true, '{"sur":"Un chez-soi, pas à pas","colonnes":[{"etiquette":"En quelques mots","pinceau":"bleu","titre":"Un accompagnement vers et dans le logement","paragraphes":["Trouver un logement ne suffit pas toujours à s’y sentir chez soi. Chez Toît accompagne les personnes avant et après leur installation : prendre leurs repères, gérer le quotidien, rompre l’isolement et créer des liens dans le quartier. L’objectif est simple : pouvoir rester chez soi durablement et éviter un retour à la rue."]},{"etiquette":"Pour qui ?","pinceau":"jaune","paragraphes":["Des adultes qui souhaitent retrouver un logement après la rue et y construire une vie stable. Deux premières rencontres permettent de faire connaissance, puis les visites s’adaptent aux besoins de chacun, au moins deux fois par mois."]}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('ct-2', '/services/chez-toit', 'texte', 2, true, '{"titre":"Nos approches (Association de Promotion du Logement)","paragraphes":["Chez Toît aide chacun à chercher un logement, à comprendre ses droits et à prendre ses marques une fois installé. L’équipe se déplace aussi à domicile et peut soutenir un projet de formation ou d’emploi. Ce travail se construit avec les partenaires du logement à Charleroi, notamment dans le cadre de Housing First."],"liste_style":"puces","liste":["Axe 1 — Accompagnement vers et dans le logement (le cœur du service)","Axe 2 — Formation & information : formations sur le logement, aide à l’inscription auprès de la Sambrienne, principalement en salle au Rebond (95 % des premiers contacts)","Axe 3 — Innovation : déploiement de deux tiny houses en 2024, pour explorer l’habitat léger et modulable, un chaînon manquant sur le territoire"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('ct-3', '/services/chez-toit', 'texte', 3, true, '{"titre":"Le type d’intervention","liste_style":"coches","colonnes":2,"liste":["Recouvrement des droits sociaux","Assistance budgétaire","Aide à la gestion de la vie quotidienne","Suivi psycho-médico-social","Appui à la création de lien avec son environnement","Affiliation à une mutuelle","Inscription à une maison médicale","Accompagnement vers une formation ou un emploi"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('ct-4', '/services/chez-toit', 'texte', 4, true, '{"titre":"Autres projets","liste_style":"puces","liste":["Plan de cohésion sociale d’Anderlues — permanence hebdomadaire de prévention","Projet « Pose ton sac » — hébergement hybride au Château de Mondron"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
