insert into public.sections (id, page, type, ordre, publie, contenu) values ('pe-1', '/services/parent-elle', 'duo', 1, true, '{"sur":"Grandir ensemble","colonnes":[{"etiquette":"En quelques mots","pinceau":"jaune","titre":"Le service Parent’Elle","paragraphes":["Parent’Elle accueille les femmes, avec ou sans enfant, ainsi que les hommes qui souhaitent avancer dans leur rôle de parent. Le service offre aux femmes et à leurs enfants un espace rien qu’à elles, et permet aux futurs parents comme aux parents de parler librement de leur quotidien et de préparer l’avenir."]},{"etiquette":"Pour qui ?","pinceau":"rouge","paragraphes":["Les femmes et leurs enfants, les femmes enceintes et les familles ayant besoin d’un espace collectif ou d’un accompagnement individualisé."]}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pe-2', '/services/parent-elle', 'texte', 2, true, '{"titre":"Un espace sécurisant et non-mixte","paragraphes":["De nombreuses femmes vivant sans logement ont connu des violences liées à leur genre. Parent’Elle leur offre depuis 18 ans un espace non mixte où elles peuvent se sentir en sécurité, être entendues et reprendre confiance, entourées de leurs enfants si elles le souhaitent."],"liste_style":"coches","liste":["Un lieu sécurisant exclusivement dédié aux femmes et à leurs enfants","Une approche genrée développée depuis 18 ans","Des activités collectives qui rompent l’isolement"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pe-3', '/services/parent-elle', 'texte_image', 3, true, '{"titre":"Un espace chaleureux, un lien de confiance","paragraphes":["Partager un café, prendre une douche, parler sans crainte : la confiance se construit dans ces gestes simples. Elle permet ensuite d’aborder la santé, le suivi médical ou la contraception. Les ateliers aident chacune à reprendre confiance, à faire ses propres choix et à sortir de l’isolement."],"image":"m-parent-elle-jeu","image_alt":"Le service Parent’Elle","rotation":1.5}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pe-4', '/services/parent-elle', 'texte', 4, true, '{"titre":"Des actions autour de la parentalité","paragraphes":["L’équipe prépare avec les parents les rencontres importantes, les aide à prendre confiance dans leur rôle et à mettre des mots sur leurs questions. Retrouver une vie avec son enfant peut devenir un appui essentiel pour sortir durablement de la rue."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pe-5', '/services/parent-elle', 'chiffres', 5, true, '{"titre":"Parent’Elle en chiffres (2022)","contexte":"service","service":"parent-elle"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
