insert into public.sections (id, page, type, ordre, publie, contenu) values ('tb-1', '/services/toudi-boudji', 'duo', 1, true, '{"sur":"On avance mieux à plusieurs","colonnes":[{"etiquette":"En quelques mots","pinceau":"vert","titre":"L’insertion sociale","paragraphes":["Toudi Boudji signifie « toujours en mouvement », un nom choisi par les personnes accueillies. Ici, des ateliers en groupe et des rencontres individuelles permettent de reprendre confiance, de créer des liens et de faire avancer un projet personnel ou professionnel."]},{"etiquette":"Pour qui ?","pinceau":"jaune","paragraphes":["Les personnes qui souhaitent rompre l’isolement, retrouver leur place, reprendre confiance et avancer vers l’autonomie. La prise de contact se fait par les professionnels de l’aide sociale."]}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('tb-2', '/services/toudi-boudji', 'texte_image', 2, true, '{"titre":"Des ateliers collectifs, pas de l’occupationnel","paragraphes":["Les ateliers ne servent pas seulement à occuper le temps. Dans un cadre détendu, chacun peut participer, essayer, parler librement et nouer une relation de confiance. Des besoins parfois difficiles à exprimer trouvent alors leur place."],"liste_style":"coches","liste":["Rompre l’isolement social","Permettre la participation à la vie sociale, économique, politique et culturelle","Promouvoir la reconnaissance sociale","Améliorer le bien-être et la qualité de vie","Favoriser l’autonomie"],"image":"m-atelier-cuisine","image_alt":"Trois personnes épluchent des légumes ensemble lors d’un atelier cuisine","rotation":-1.5}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('tb-3', '/services/toudi-boudji', 'texte', 3, true, '{"titre":"Un suivi individualisé","paragraphes":["Les ateliers et les rencontres individuelles se complètent. Le lien construit au fil du temps permet de parler de ce qui compte vraiment, puis d’engager des démarches concrètes et d’imaginer la suite."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('tb-4', '/services/toudi-boudji', 'texte', 4, true, '{"titre":"Un travail ancré dans l’approche à 360°","paragraphes":["Les ateliers prennent encore plus de sens lorsqu’ils avancent avec les autres services. En retrouvant des liens et de la confiance, les participants sont mieux armés pour faire face au quotidien, notamment pour chercher un logement et s’y installer."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('tb-5', '/services/toudi-boudji', 'texte', 5, true, '{"titre":"Décret insertion sociale","paragraphes":["Le service accueille des adultes de 18 à 67 ans qui traversent une période d’éloignement social ou professionnel. Son cadre officiel poursuit des objectifs très concrets : sortir de l’isolement, participer à la vie collective, retrouver du bien-être et gagner en autonomie."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
