insert into public.sections (id, page, type, ordre, publie, contenu) values ('ps-2', '/services/promotion-sante', 'texte', 2, true, '{"titre":"La santé, au plus près des personnes","paragraphes":["Depuis 2023, notre programme de promotion de la santé relie prévention, écoute et accompagnement. Il part des questions et des besoins rencontrés dans la vie quotidienne, pour rendre les soins plus accessibles et aider chacun à devenir acteur de sa santé."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('ps-3', '/services/promotion-sante', 'cartes_texte', 3, true, '{"titre":"Prévenir, écouter et accompagner","cartes":[{"titre":"Prévenir","texte":"Des temps d’information et de sensibilisation pour mieux comprendre sa santé et repérer les situations qui demandent de l’attention."},{"titre":"Soigner","texte":"Une présence de proximité pour écouter, orienter et faciliter l’accès aux soins lorsque les démarches semblent trop difficiles."},{"titre":"Partager","texte":"Des échanges où l’expérience de chacun compte, pour rompre l’isolement et retrouver des repères utiles au quotidien."}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('ps-4', '/services/promotion-sante', 'texte', 4, true, '{"titre":"Une équipe qui travaille ensemble","paragraphes":["Un médecin bénévole, une infirmière, une psychologue et une équipe de soins à domicile croisent leurs regards. Ensemble, ils proposent une présence attentive et des réponses adaptées à la réalité de chaque personne."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
