insert into public.sections (id, page, type, ordre, publie, contenu) values ('ac-1', '/', 'accueil_hero', 1, true, '{"titre":"Des parcours\nqui se croisent.\nDes liens qui\nse tissent.","texte":"À Charleroi, nous accueillons, écoutons et accompagnons les personnes en situation de précarité, vers une sortie durable de la rue.","portrait":"m-hero-rebond","portrait_alt":"Portrait d’un homme souriant, bonnet de laine, regard tourné vers le haut","decor":"m-hero-immeuble","boutons":[{"libelle":"Découvrir l’association","lien":"/association","style":"plein","icone":"fleche"},{"libelle":"Nous soutenir","lien":"/soutenir","style":"contour","icone":"coeur"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
