insert into public.sections (id, page, type, ordre, publie, contenu) values ('ac-4', '/', 'liens_actus', 4, true, '{"etiquette":"Actualités\n& ressources","liens":[{"libelle":"Publications\net guides","lien":"/actualites","icone":"livre"},{"libelle":"Projets\nen cours","lien":"/actualites","icone":"calendrier"},{"libelle":"Événements\net actions","lien":"/actualites","icone":"megaphone"},{"libelle":"Ressources\nutiles","lien":"/actualites","icone":"pousse"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
