insert into public.sections (id, page, type, ordre, publie, contenu) values ('sv-1', '/services', 'tete', 1, true, '{"sur":"Nos services","theme":"rouge","titre":"Chaque besoin a sa porte d’entrée.","chapo":"Quatre services complémentaires, une seule ambition : accompagner la personne dans toutes les dimensions de sa vie.","fil":["rouge","bleu","jaune","vert"],"image":"m-echange-sourires-detoure","image_alt":"Un jeune homme et une intervenante échangent en riant"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('sv-2', '/services', 'rangs_services', 2, true, '{"titre":"Quatre portes, une même maison.","intro":"L’accompagnement à 360° : les services ne sont pas cloisonnés, ils s’articulent autour de la personne.","bouton":"Découvrir","rangs":[{"service":"le-rebond","texte":"Au Rebond, chacun peut d’abord souffler, manger, se laver et être écouté. C’est souvent dans ces moments simples qu’un lien se crée.","image":"m-service-rebond","image_alt":"Trois hommes rient autour d’un café au Rebond","rotation":-1.5},{"service":"chez-toit","texte":"Trouver un logement ne suffit pas toujours à s’y sentir chez soi. Chez Toît accompagne les personnes avant et après leur installation : prendre leurs repères, gérer le quotidien, rompre l’isolement et créer des liens dans le quartier.","image":"m-chez-toit-cles","image_alt":"Le service Chez Toît","rotation":1.5},{"service":"toudi-boudji","texte":"Toudi Boudji signifie « toujours en mouvement », un nom choisi par les personnes accueillies. Ici, des ateliers en groupe et des rencontres individuelles permettent de reprendre confiance, de créer des liens et de faire avancer un projet personnel ou professionnel.","image":"m-service-toudi-boudji","image_alt":"Trois hommes de dos, bras sur les épaules","rotation":-1},{"service":"parent-elle","texte":"Parent’Elle accueille les femmes, avec ou sans enfant, ainsi que les hommes qui souhaitent avancer dans leur rôle de parent. Le service offre aux femmes et à leurs enfants un espace rien qu’à elles, et permet aux futurs parents comme aux parents de parler librement de leur quotidien et de préparer l’avenir.","image":"m-service-parent-elle","image_alt":"Une mère et sa fille accompagnées par Parent’Elle, souriantes","rotation":1.5},{"service":"promotion-sante","texte":"La santé fait partie du chemin. Nous créons des occasions simples de parler, de prévenir, de recevoir des soins et de retrouver confiance, sans jugement et au rythme de chacun.","image":"","image_alt":""}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('sv-3', '/services', 'transversal', 3, false, '{}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
