insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-1', '/association', 'tete', 1, true, '{"sur":"L’association","titre":"À hauteur d’humain, depuis 1995.","chapo":"À Charleroi, Comme Chez Nous propose un accueil et un accompagnement humain, social et médical aux personnes sans logement.","image":"m-asso-equipe","image_alt":"L’accueil de Comme Chez Nous à Charleroi","rotation":-1.5,"boutons":[{"libelle":"Découvrir nos services","lien":"/services","style":"c","icone":"fleche"}],"fil":["rouge"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-2', '/association', 'deux_colonnes', 2, true, '{"colonnes":[{"sur":"Notre mission","titre":"Accueillir sans condition.","paragraphes":["Depuis 1995, Comme Chez Nous accueille, écoute et accompagne les personnes en situation de grande précarité à Charleroi, vers une sortie durable de la rue."],"liste":["Ouvert 7j/7, 365 jours par an","Accueil inconditionnel"],"signature":"Sophie Crapez, directrice"},{"sur":"Notre manière d’agir","theme":"bleu","titre":"Notre approche à 360°","paragraphes":["Vivre sans logement touche bien plus qu’une adresse. La santé, les papiers, la famille, les liens avec les autres ou le retour vers l’emploi peuvent aussi devenir difficiles. Nos services travaillent ensemble pour que la personne n’ait pas à raconter son histoire à chaque porte et puisse avancer à son rythme."]}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-3', '/association', 'chiffres', 3, true, '{"sur":"En 2023, à Comme Chez Nous","contexte":"association"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-4', '/association', 'chiffres', 4, true, '{"sur":"À Charleroi","titre":"Le sans-abrisme en chiffres","contexte":"charleroi"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-5', '/association', 'texte_image', 5, true, '{"theme":"vert","titre":"Nos enjeux & défis","paragraphes":["De plus en plus de personnes viennent frapper à notre porte, alors que nos locaux sont devenus trop petits. Nous voulons continuer à accueillir chacun dignement et offrir à nos équipes un lieu adapté pour bien travailler."],"liste_style":"coches","liste":["Des locaux plus dignes et adaptés","Une réponse à l’augmentation des besoins","De bonnes conditions de travail pour les équipes","Un chantier pour doubler la superficie et atteindre 1 200 m²"],"image":"m-rebond-repas","image_alt":"Un repas partagé au Rebond","rotation":1.5,"image_position":"gauche"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-6', '/association', 'reperes', 6, true, '{"sur":"Depuis 1995","titre":"Une histoire ancrée à Charleroi.","intro":"Comme Chez Nous est née en 1995, portée par des personnes démunies et des bénévoles. En 2000, l’association participe à la création du Relais Social de Charleroi et peut engager ses premiers travailleurs. Depuis 2002, elle concentre son action auprès des personnes sans logement. Cette histoire collective est racontée dans l’ouvrage « Construire avec les Naufragés » (2020)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-7', '/association', 'valeurs', 7, true, '{"sur":"Ce qui nous guide","titre":"Accueillir d’abord. Construire ensuite."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('as-8', '/association', 'equipe', 8, true, '{"sur":"Celles et ceux qui font vivre la maison","titre":"L’équipe","paragraphes":["Une trentaine de personnes font vivre Comme Chez Nous au quotidien : assistants sociaux, éducateurs, infirmière, psychologue, professionnels de la santé, psychomotricien, équipe administrative et de nombreux bénévoles. Des métiers différents, réunis autour d’une même attention aux personnes."],"image":"m-echange-sourires","image_alt":"Un jeune homme et une intervenante échangent en riant","rotation":-1,"boutons":[{"libelle":"Devenir bénévole","lien":"/soutenir/benevolat","style":"nuit","icone":"fleche"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
