insert into public.sections (id, page, type, ordre, publie, contenu) values ('so-1', '/soutenir', 'tete', 1, true, '{"sur":"Nous aider","titre":"Nous aider","accroche":"Chaque geste compte","chapo":"Don, bénévolat ou partenariat : chaque forme de soutien renforce l’accueil inconditionnel à Charleroi.","image":"m-don-mains","image_alt":"Une poignée de main","rotation":-1.5,"boutons":[{"libelle":"Faire un don","lien":"/soutenir/don","style":"plein","icone":"coeur"}],"fil":["rouge"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('so-2', '/soutenir', 'cartes_liens', 2, true, '{"sur":"Toutes les façons d’aider","titre":"Choisissez votre manière de soutenir","cartes":[{"titre":"Faire un don","texte":"Votre don finance directement l’accueil, l’accompagnement et le grand projet de reconstruction.","lien":"/soutenir/don","bouton":"En savoir plus"},{"titre":"Don en nature","texte":"Vêtements, produits d’hygiène, couvertures, matériel de cuisine : vos dons en nature servent directement aux personnes accueillies.","lien":"/soutenir/don-en-nature","bouton":"En savoir plus"},{"titre":"Devenir bénévole","texte":"Nous sommes constamment à la recherche de bénévoles : distribution du café, tâches administratives, gestion de bases de données… peu importe vos compétences, nous trouverons un poste qui vous correspond.","lien":"/soutenir/benevolat","bouton":"En savoir plus"},{"titre":"Mécénat d’entreprise & teambuilding","texte":"Entreprises : soutenez un projet concret ou venez vivre une journée solidaire avec votre équipe, au plus près du terrain.","lien":"/soutenir/partenariat","bouton":"En savoir plus"},{"titre":"Devenir partenaire","texte":"Entreprises, associations et institutions : sponsoring, mécénat et soutien aux missions. Construisons une collaboration utile au territoire.","lien":"/partenaires","bouton":"En savoir plus"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('so-3', '/soutenir', 'texte', 3, true, '{"sur":"Notre grand projet","titre":"Comme Chez Nous se redessine","paragraphes":["Une meilleure articulation entre les services, une augmentation de l’offre et des économies d’énergie.","Un vaste chantier de déconstruction et reconstruction des bâtiments historiques rue de Charleville 36, 38 et 40 est mené avec Atelier4D. Objectif : doubler la superficie dédiée aux missions pour atteindre 1 200 m², améliorer l’accueil et créer de nouveaux logements temporaires."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('so-4', '/soutenir', 'partenaires', 4, true, '{"sur":"Ils nous soutiennent","titre":"Partenaires de Comme Chez Nous","type":"financeur"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('do-1', '/soutenir/don', 'tete', 1, true, '{"sur":"Nous aider","titre":"Votre soutien nous est précieux. Chaque geste compte.","accroche":"Merci d’être là","chapo":"Votre don finance directement l’accueil, l’accompagnement et les projets de reconstruction pour sortir durablement les personnes de la rue et de la grande précarité.","image":"m-tasse-partagee-detoure","image_alt":"Une main tend une tasse chaude à une autre main","rotation":-1.5,"fil":["rouge"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('do-2', '/soutenir/don', 'virement', 2, true, '{"sur":"Don financier","titre":"Faire un don par virement","libelle_iban":"IBAN","libelle_beneficiaire":"Bénéficiaire","bouton_copier":"Copier l’IBAN","copie_ok":"IBAN copié","communication":"N’oubliez pas d’indiquer vos coordonnées (nom, prénom, adresse) en communication pour recevoir votre attestation fiscale.","bon_a_savoir_titre":"Bon à savoir","qr_legende":"Scannez avec votre app bancaire","qr_alt":"QR code de virement SEPA vers l’ASBL Comme Chez Nous"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('do-3', '/soutenir/don', 'cartes_liens', 3, true, '{"titre":"Deux façons de nous aider","cartes":[{"titre":"Don financier","texte":"Un virement ponctuel ou permanent, déductible fiscalement.","lien":"#virement","bouton":"Faire un virement"},{"titre":"Don matériel","texte":"Vêtements, hygiène, matériel : ce qui est utile au quotidien.","lien":"/soutenir/don-en-nature","bouton":"Voir les besoins"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('do-4', '/soutenir/don', 'texte', 4, true, '{"titre":"À quoi servent vos dons ?","liste_style":"coches","liste":["Achat de denrées alimentaires","Achat de matériel d’hygiène","Création de possibilités de relogement (temporaires ou non)","Investissement en matériel d’accueil pour le nouveau centre"],"sous_titre":"Toute l’année","sous_texte":"Poursuivre notre action d’accueil et d’accompagnement 365 jours par an, à travers les axes d’intervention de notre approche à 360°."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
