insert into public.sections (id, page, type, ordre, publie, contenu) values ('be-1', '/soutenir/benevolat', 'tete', 1, true, '{"sur":"Nous aider","titre":"Devenez bénévole chez Comme Chez Nous","accroche":"Un peu de temps, beaucoup de lien","chapo":"Donnez un peu de votre temps, changez une vie.","image":"m-atelier-cuisine-detoure","image_alt":"Trois personnes épluchent des légumes ensemble lors d’un atelier cuisine","rotation":-1.5,"fil":["rouge"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('be-2', '/soutenir/benevolat', 'texte', 2, true, '{"titre":"Le bénévolat, dans notre ADN","paragraphes":["Nos bénévoles sont une part essentielle de notre association. Comme Chez Nous a été créée en 1995 par et pour des personnes démunies, et fonctionnait à l’origine uniquement grâce au volontariat. Aujourd’hui encore, aux côtés de notre équipe pluridisciplinaire d’une trentaine de salariés, nos bénévoles font vivre l’accueil au quotidien et sont au cœur de nos missions."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('be-3', '/soutenir/benevolat', 'texte', 3, true, '{"sur":"S’engager à nos côtés","titre":"Ce que vous pouvez faire","paragraphes":["Peu importe vos compétences, votre disponibilité ou votre expérience : nous trouverons un rôle qui vous correspond. Quelques exemples :"],"liste_style":"coches","colonnes":2,"liste":["Distribution du café et des repas","Écoute et présence auprès des personnes accueillies","Aide aux ateliers (cuisine, sport, activités collectives)","Tâches administratives","Gestion de bases de données","Soutien logistique et événementiel"],"apres_liste":"Cette liste n’est pas exhaustive — parlez-nous de vos envies et de vos talents, on trouvera ensemble votre place."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('be-4', '/soutenir/benevolat', 'cartes_texte', 4, true, '{"sur":"Une expérience qui compte","titre":"Pourquoi devenir bénévole chez nous","numeros":true,"cartes":[{"texte":"Rejoindre une équipe engagée et bienveillante"},{"texte":"Agir concrètement contre le sans-abrisme et la grande précarité, à Charleroi"},{"texte":"Vivre une expérience humaine forte, au plus près des personnes"},{"texte":"Être formé·e et accompagné·e dans votre rôle"}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('be-5', '/soutenir/benevolat', 'formulaire', 5, true, '{"formulaire":"benevolat","sur":"Votre candidature","titre":"Prêt·e à nous rejoindre ?","intro":"Dites-nous quand vous êtes disponible et ce que vous aimeriez faire. Nous vous recontacterons pour en parler simplement.","bouton":"Envoyer ma candidature","encart_titre":"Une question avant de vous lancer ?","encart_texte":"contact@asblcommecheznous.be · 0495 35 24 26","encart_boutons":[{"libelle":"Écrire","lien":"mailto:contact@asblcommecheznous.be","style":"contour"},{"libelle":"Appeler","lien":"tel:+32495352426","style":"contour"}],"message_envoye":"Merci, votre message a bien été envoyé. Nous vous recontacterons rapidement.","message_erreur":"L’envoi n’a pas fonctionné. Vous pouvez réessayer ou nous écrire à contact@asblcommecheznous.be.","message_invalide":"Merci de compléter les champs obligatoires (marqués d’un astérisque)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
