insert into public.sections (id, page, type, ordre, publie, contenu) values ('pr-1', '/soutenir/partenariat', 'tete', 1, true, '{"sur":"Devenir partenaire / mécène","titre":"Devenez partenaire de nos projets","accroche":"Construire ensemble","chapo":"Comme Chez Nous traverse un tournant majeur de son histoire. Nous cherchons des partenaires soucieux de réduire les inégalités sociales et prêts à soutenir nos projets, au bénéfice des personnes que nous accompagnons et de nos équipes.","image":"m-don-mains","image_alt":"Une poignée de main","rotation":-1.5,"fil":["rouge"]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pr-2', '/soutenir/partenariat', 'texte', 2, true, '{"sur":"Le projet à soutenir","titre":"Déconstruire pour mieux reconstruire","paragraphes":["Notre association entreprend un vaste chantier de déconstruction et de reconstruction de ses locaux historiques (rue de Charleville), confié au bureau d’architecture Atelier4D. La nouvelle configuration permettra de doubler la superficie dédiée à nos missions, portant à 1 200 m² la surface totale du Centre d’accueil de jour et de l’ensemble des services, et de créer de nouveaux logements temporaires."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pr-3', '/soutenir/partenariat', 'texte', 3, true, '{"sur":"Pourquoi","titre":"Pourquoi nous soutenir","paragraphes":["Malgré les défis économiques, notre ASBL a toujours maintenu une gestion financière saine. Votre engagement à nos côtés permet de bâtir l’avenir de l’association et de poursuivre nos missions pour endiguer le sans-abrisme."]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('pr-4', '/soutenir/partenariat', 'cartes_texte', 4, true, '{"sur":"Comment","titre":"Comment votre entreprise peut s’engager","intro":"Il existe plusieurs façons de nous rejoindre. Choisissons ensemble celle qui correspond à votre entreprise.","cartes":[{"titre":"Mécénat d’entreprise","texte":"Un soutien financier à un projet précis — le chantier de reconstruction, un atelier, un service — avec un suivi régulier de ce que votre contribution a permis."},{"titre":"Teambuilding solidaire","texte":"Une journée avec votre équipe sur le terrain : rénovation, cuisine, logistique. Une expérience humaine forte, utile et encadrée par nos équipes."},{"titre":"Don en nature","texte":"Matériel, équipements, produits ou compétences : vos ressources peuvent répondre directement à nos besoins quotidiens."}]}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
