insert into public.sections (id, page, type, ordre, publie, contenu) values ('pr-7', '/soutenir/partenariat', 'budget', 7, true, '{"titre":"Le budget","paragraphes":["Budget total du projet : environ 2,7 millions d’euros. 1,8 million déjà mobilisés en deniers publics. Il reste 1 million d’euros à récolter."],"note":"La flambée des prix des matériaux (+35 %) a fortement grevé l’enveloppe initiale.","bon_a_savoir_titre":"Bon à savoir","bon_a_savoir":"Pour tout don à partir de 40 € sur base annuelle, une attestation fiscale permet de récupérer 45 % du montant sous forme de réduction d’impôts.","bouton":"Lire plus"}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
