insert into public.sections (id, page, type, ordre, publie, contenu) values ('cf-2', '/confidentialite', 'texte', 2, true, '{"sur":"Responsable du traitement","titre":"Qui est responsable de vos données ?","paragraphes":["L’ASBL Comme Chez Nous est responsable des données recueillies sur ce site."],"coordonnees":true,"a_valider":true,"note_interne":"À compléter : numéro d’entreprise et personne de contact pour la vie privée. Source : DONNEES-PERSONNELLES.md (14/11/2026)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('cf-3', '/confidentialite', 'donnees_formulaires', 3, true, '{"sur":"Données collectées","titre":"Ce que nous recueillons par les formulaires","intro":"Nous recueillons uniquement ce qui est nécessaire pour répondre à votre demande. Vos informations ne sont ni revendues ni partagées.","libelle_champs":"Données","libelle_duree":"Conservation","formulaires":[{"formulaire":"contact","nom":"Contact","but":"Répondre à votre demande","duree":"12 mois après réception"},{"formulaire":"benevolat","nom":"Bénévolat","but":"Étudier votre candidature et vous recontacter","duree":"24 mois après réception"},{"formulaire":"partenariat","nom":"Partenariat","but":"Vous envoyer le dossier et suivre la relation","duree":"24 mois après réception"}],"note":"Nous enregistrons aussi le type de formulaire ainsi que la date et l’heure d’envoi. Aucune adresse IP n’est enregistrée. Passé le délai, les messages sont supprimés automatiquement.","a_valider":false,"note_interne":"Durées validées par Charlotte le 14/11/2026. Source : DONNEES-PERSONNELLES.md (14/11/2026)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('cf-4', '/confidentialite', 'texte', 4, true, '{"sur":"Vos droits","titre":"Vous gardez la main","paragraphes":["Vous pouvez demander l’accès à vos données, leur rectification ou leur effacement, ou vous opposer à leur traitement, en écrivant à l’association. Nous répondons dans un délai d’un mois.","Vous pouvez aussi introduire une plainte auprès de l’Autorité de protection des données (autoriteprotectiondonnees.be)."],"a_valider":true,"note_interne":"Délai de réponse d’un mois = délai légal RGPD ; à confirmer par l’association. Source : DONNEES-PERSONNELLES.md (14/11/2026)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('cf-5', '/confidentialite', 'texte', 5, true, '{"sur":"Cookies","titre":"Cookies et services extérieurs","paragraphes":["Le site public n’utilise aucun cookie.","La carte de la page d’aide charge ses fonds de plan depuis OpenStreetMap, qui reçoit donc l’adresse IP des visiteurs de cette page.","La fonction « Centres près de moi » calcule votre position dans votre appareil : elle n’est jamais envoyée ni enregistrée."],"a_valider":true,"note_interne":"À revoir si une mesure d’audience est activée (Vercel Web Analytics, sans cookie). Source : DONNEES-PERSONNELLES.md (14/11/2026)."}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
insert into public.sections (id, page, type, ordre, publie, contenu) values ('cf-6', '/confidentialite', 'texte', 6, true, '{"sur":"Contact","titre":"Une question sur vos données ?","paragraphes":["Écrivez-nous ou passez à l’accueil : nous vous répondrons."],"coordonnees":true,"a_valider":false}'::jsonb) on conflict (id) do update set page = excluded.page, type = excluded.type, ordre = excluded.ordre, publie = excluded.publie, contenu = excluded.contenu;
