insert into public.temoignages (id, service, texte, auteur, ordre, publie) values ('t-ct-1', 'chez-toit', 'Pour certains, la visite que nous rendons à domicile est le seul contact de la journée. On prend le temps de discuter et de s’assurer que la personne va bien. Tout se fait sur base volontaire.', 'Un travailleur social', 1, true) on conflict (id) do update set service = excluded.service, texte = excluded.texte, auteur = excluded.auteur, ordre = excluded.ordre, publie = excluded.publie;
insert into public.temoignages (id, service, texte, auteur, ordre, publie) values ('t-ct-2', 'chez-toit', 'En rue, tu n’es jamais physiquement seul. Dans tes 4 murs, il n’y a plus personne, tu te retrouves seul avec toi-même et tu n’en as pas forcément envie.', 'Edmond (prénom d’emprunt)', 2, true) on conflict (id) do update set service = excluded.service, texte = excluded.texte, auteur = excluded.auteur, ordre = excluded.ordre, publie = excluded.publie;
insert into public.temoignages (id, service, texte, auteur, ordre, publie) values ('t-pe-1', 'parent-elle', 'J’ai poussé la porte de Parent’Elle lorsque mes deux grandes filles, de 15 et 17 ans, sont rentrées à la maison. Parent’Elle m’a aidée dans mon rôle de parent et dans la gestion de conflits avec mes adolescentes en crise. J’ai aussi réussi à obtenir des visites encadrées avec ma petite dernière, qui est en famille d’accueil. Par la suite, j’ai participé à des ateliers d’estime de soi où j’ai pu retrouver ma confiance en moi.', 'Christelle, 42 ans', 1, true) on conflict (id) do update set service = excluded.service, texte = excluded.texte, auteur = excluded.auteur, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-accueil', '/', '', 'Les services de Comme Chez Nous et les contacts d’urgence à Charleroi.', 'rouge', 1, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-services', '/services', 'Nos services', 'Le Rebond, Chez Toît, Parent’Elle, Toudi Boudji et la Promotion de la santé : cinq services pour accompagner chaque personne vers une sortie durable de la rue.', 'nuit', 2, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-association', '/association', 'L’association', 'Accueil et accompagnement à Charleroi depuis 1995.', 'rouge', 3, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-soutenir', '/soutenir', 'Nous aider', 'Don, don en nature, bénévolat, mécénat ou partenariat : toutes les façons de soutenir l’accueil inconditionnel de Comme Chez Nous à Charleroi.', 'rouge', 4, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-don', '/soutenir/don', 'Faire un don', 'Faites un don à Comme Chez Nous : il finance l’accueil, l’accompagnement et le projet de reconstruction. Virement simple, déductible fiscalement.', 'rouge', 5, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-nature', '/soutenir/don-en-nature', 'Donner en nature', 'Vêtements, hygiène, matériel : ce qui dort chez vous peut servir ici. Découvrez les besoins de Comme Chez Nous et comment déposer vos dons.', 'rouge', 6, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
