insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-contact', '/contact', 'Contact', 'Contacter Comme Chez Nous à Charleroi : téléphone, e-mail, adresse et formulaire. Une question, une demande ou un projet ? La porte est ouverte.', 'bleu', 9, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
insert into public.pages (id, adresse, titre, description, theme, ordre, publie) values ('p-aide', '/aide', 'J’ai besoin d’aide à Charleroi', 'Où trouver de l’aide à Charleroi : accueils de jour, hébergement, repas, soins, logement. Carte des lieux et numéros d’urgence, 24 h/24.', 'rouge', 10, true) on conflict (id) do update set adresse = excluded.adresse, titre = excluded.titre, description = excluded.description, theme = excluded.theme, ordre = excluded.ordre, publie = excluded.publie;
