insert into public.articles (id, slug, titre, categorie, date_affichee, date_publication, resume, corps, image, image_alt, service, lien_externe, exemple, ordre, publie) values ('a-peau-neuve', 'comme-chez-nous-fait-peau-neuve', 'Comme Chez Nous fait peau neuve', 'Actualité', '10 novembre 2026', '2026-11-10', 'Même ASBL, mêmes équipes : un site plus clair pour trouver facilement nos services.', '<p>Notre site fait peau neuve ! Même ASBL, mêmes équipes, mêmes coordonnées : nous avons simplement repensé le site pour que vous trouviez plus facilement nos services, nos actualités et la manière de nous contacter.</p>', 'm-echange-brochures', 'Une intervenante sourit à un homme assis en face d’elle, des brochures posées sur la table', null, '', false, 1, true) on conflict (id) do update set slug = excluded.slug, titre = excluded.titre, categorie = excluded.categorie, date_affichee = excluded.date_affichee, date_publication = excluded.date_publication, resume = excluded.resume, corps = excluded.corps, image = excluded.image, image_alt = excluded.image_alt, service = excluded.service, lien_externe = excluded.lien_externe, exemple = excluded.exemple, ordre = excluded.ordre, publie = excluded.publie;
insert into public.articles (id, slug, titre, categorie, date_affichee, date_publication, resume, corps, image, image_alt, service, lien_externe, exemple, ordre, publie) values ('a-redessine', 'comme-chez-nous-se-redessine', 'Comme Chez Nous se redessine : le projet immobilier', 'Projet', '2026', null, 'Deux chantiers pour accueillir mieux et plus dignement : rue de Charleville et rue Dagnelies.', '<p>Pour offrir un accueil plus digne et mieux adapté, Comme Chez Nous engage deux chantiers majeurs à Charleroi.</p><h2>Rue de Charleville</h2><p>2 263 266 € : achat du bâtiment n°40 et travaux des n°36, 38 et 40, pour rassembler l’accueil de jour et l’accompagnement dans des lieux accessibles et chaleureux.</p><h2>Rue Dagnelies</h2><p>686 550 € : achat du bâtiment, mise en conformité et rénovation énergétique, pour des logements plus sûrs et moins énergivores.</p><h2>Comment aider ?</h2><p>Chaque don, même modeste, rapproche ces projets de leur réalisation.</p>', '', '', null, '', false, 2, true) on conflict (id) do update set slug = excluded.slug, titre = excluded.titre, categorie = excluded.categorie, date_affichee = excluded.date_affichee, date_publication = excluded.date_publication, resume = excluded.resume, corps = excluded.corps, image = excluded.image, image_alt = excluded.image_alt, service = excluded.service, lien_externe = excluded.lien_externe, exemple = excluded.exemple, ordre = excluded.ordre, publie = excluded.publie;
